		&UploadCommand;




var f = this, g = f.grid, k = f.getItem('ticket').value, importMemvars = [];
var fileName = get$&Identity;FileName($get('fileupload').value), allowExt = 'xlsx';
var err = (this._language == 'v' ? 'Định dạng tệp không đúng.' : 'Invalid file type.');
if (fileName != '') {
	var ext = fileName.split('.').pop();
	if (allowExt.indexOf(ext.toLowerCase()) < 0) {
		f._checked = false;
		$message.show(err);
	}
	else {
		init$&Identity;IFrame(f);
		set$&Identity;Memvar(f, importMemvars, 'type');
		&FilterFormModeVar;
		var controller = g._controller; 

		if (f.getItemValue('category') == '2') controller += 'Payment';
		if (f.getItemValue('category') == '3') controller += 'PaymentTL';
		if (f.getItemValue('category') == '4') controller += 'CTBL';
		if (f.getItemValue('category') == '7') controller += 'HisCustomer';

		var form = $get('uploadForm'), query = {Language: f._language, Controller: controller, Key: k, Memvars: importMemvars, Time:new Date().getTime().toString()};
		$get('query', form).value = Sys.Serialization.JavaScriptSerializer.serialize(query);
		form.action = $func.resolveClientUrl('~/AppHandler/Import.ashx', g._baseUrl);
		form.target = g._controller + '_IFrame';
		form.submit();
		f.request('GetTicket', 'GetTicket', []);
		f._checked = false;
		&FilterFormModeEndSubmit;
	}
}







			&OutlineEntry;
			&UploadScript;
			&FilterFormModeScript;

function init$&Identity;(f) {
	var g = f.grid;
	document.body._form = f;
	$get('fileupload').value = '';
	f.getItem('upload').field.AllowNulls = false;
	$get(f.get_id() + '_form_upload').style.color = 'grey';
	f.request('GetTicket', 'GetTicket', []);
}
function on$&Identity;$ResponseComplete(f, e) {
	var f = e.object, g = f.grid, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'GetTicket':
			f.setItemValue('ticket', result[0].Value);
			break;
		default:
			break;
	}
}
function onChange$&Identity;$category(o) {
	var f = o.parentForm, type = f.getItem('type');
	if (o.value == '2' || o.value == '3' || o.value == '4') {
		f.setItemValue('type', '1');
		f._setReadOnly(type, true);
		return;
	}
	f._setReadOnly(type, false);
}







